  const L = {
    lang: 'en',
    langs: [{ id: 'tr', name: 'Türkçe', tts: 'tr' }, { id: 'en', name: 'English', tts: 'en' }, { id: 'de', name: 'Deutsch', tts: 'de' }, { id: 'es', name: 'Español', tts: 'es' }],
    dict: { en, tr, de, es },
    set(l) { this.lang = this.dict[l] ? l : 'en'; document.documentElement.lang = this.lang; },
    raw(k) { const d = this.dict[this.lang]; return d[k] != null ? d[k] : en[k]; },
    t(k, ...args) {
      let s = this.raw(k);
      if (s == null) return k;
      if (typeof s === 'string' && args.length) s = s.replace(/\{(\d)\}/g, (m, i) => (args[i] != null ? args[i] : ''));
      return s;
    },
    pick(k) { const a = this.raw(k); return Array.isArray(a) ? a[Math.floor(Math.random() * a.length)] : a; },
    room(name) {
      const map = this.raw('room') || {};
      const m = /^([0-9A-Z]{1,3}\s)?(.*)$/.exec(name);
      const pre = m && m[1] && /\d/.test(m[1]) ? m[1] : '';
      const base = pre ? name.slice(pre.length) : name;
      return pre + (map[base] || base);
    },
    detect() { const n = (navigator.language || 'en').slice(0, 2).toLowerCase(); return this.dict[n] ? n : 'en'; }
  };
  TR.L = L;
  TR.t = (...a) => L.t(...a);
